// Sound contract. UI code calls Sound.play(Sfx.x) and never touches players
// directly. Assets live in assets/audio/<Sfx.name>.mp3 and are generated by
// tool/audio/generate_audio.py.
//
// Rules this file follows:
// - Audio must never crash the game: every plugin call is guarded.
// - Browsers block audio until a user gesture, so music starts lazily on the
//   first play() (always triggered by a tap) when it could not start earlier.
// - Preferences (muted, musicOn) persist via shared_preferences.

import 'dart:async';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/widgets.dart';
import 'package:shared_preferences/shared_preferences.dart';

enum Sfx {
  click,
  purchase,
  upgrade,
  trainingStart,
  trainingDone,
  release,
  stuntFail,
  eraUp,
  rivalBeaten,
  viralAlarm,
  error,
}

abstract final class Sound {
  /// Asset path (relative to `assets/`) for a sound effect.
  static String assetFor(Sfx sfx) => 'audio/${sfx.name}.mp3';
  static const String musicAsset = 'audio/music_loop.mp3';

  /// Music volume (the SFX play on top of it).
  static const double musicVolume = 0.35;

  /// Minimum gap between two plays of the same effect.
  static const Duration throttle = Duration(milliseconds: 60);

  /// Per-effect volume, balanced by ear against the music. Frequent sounds
  /// are quieter so hours of clicking stay pleasant.
  static double sfxVolume(Sfx sfx) => switch (sfx) {
    Sfx.click => 0.4,
    Sfx.purchase => 0.6,
    Sfx.upgrade => 0.65,
    Sfx.trainingStart => 0.6,
    Sfx.trainingDone => 0.7,
    Sfx.release => 0.8,
    Sfx.stuntFail => 0.7,
    Sfx.eraUp => 0.85,
    Sfx.rivalBeaten => 0.85,
    Sfx.viralAlarm => 0.6,
    Sfx.error => 0.55,
  };

  static int _poolSize(Sfx sfx) => switch (sfx) {
    Sfx.click => 4,
    Sfx.purchase => 4,
    Sfx.upgrade => 3,
    Sfx.error => 2,
    _ => 2,
  };

  static const _kMuted = 'sound.muted';
  static const _kMusicOn = 'sound.musicOn';

  /// Notifies listeners (e.g. a settings toggle) when muted/musicOn change.
  static final ValueNotifier<int> changes = ValueNotifier<int>(0);

  static bool _muted = false;
  static bool _musicOn = true;

  static bool get muted => _muted;
  static set muted(bool value) => setMuted(value);
  static bool get musicOn => _musicOn;
  static set musicOn(bool value) => setMusicOn(value);

  /// Forces the audio backend on or off. Null means auto-detect (off under
  /// `flutter test`, where the audio plugin is not registered).
  @visibleForTesting
  static bool? debugBackendOverride;

  /// Number of play() calls that passed the mute and throttle checks.
  @visibleForTesting
  static int debugAccepted = 0;

  static Future<void>? _initFuture;
  static bool _backend = false;
  static SharedPreferences? _prefs;
  static AppLifecycleListener? _lifecycle;

  static final Map<Sfx, Future<_SfxPool?>> _pools = {};
  static Future<AudioPlayer?>? _musicFuture;
  static Future<void>? _musicStarting;
  static bool _musicPlaying = false;
  static bool _inBackground = false;
  static int _lastMusicAttemptMs = -100000;

  static final Stopwatch _clock = Stopwatch()..start();
  static final Map<Sfx, int> _lastPlayedMs = {};

  /// Loads preferences and starts preloading audio in the background.
  /// Safe to call more than once; never throws and never blocks for long.
  static Future<void> init() => _initFuture ??= _init();

  static Future<void> _init() async {
    try {
      _backend = debugBackendOverride ?? !_isTestEnvironment();
      try {
        _prefs = await SharedPreferences.getInstance().timeout(
          const Duration(seconds: 2),
        );
        _muted = _prefs?.getBool(_kMuted) ?? false;
        _musicOn = _prefs?.getBool(_kMusicOn) ?? true;
        changes.value++;
      } catch (e) {
        _log('prefs unavailable: $e');
      }
      if (!_backend) return;
      _lifecycle ??= AppLifecycleListener(onStateChange: _onLifecycle);
      await _configureAudioContext();
      for (final sfx in Sfx.values) {
        _pools[sfx] = _SfxPool.create(sfx);
      }
      _musicFuture = _createMusicPlayer();
    } catch (e) {
      _log('init failed: $e');
    }
  }

  /// Plays a sound effect. Fire-and-forget; never throws.
  static void play(Sfx sfx) {
    try {
      if (_initFuture == null) unawaited(init());
      if (_muted) return;
      final now = _clock.elapsedMilliseconds;
      final last = _lastPlayedMs[sfx];
      if (last != null && now - last < throttle.inMilliseconds) return;
      _lastPlayedMs[sfx] = now;
      debugAccepted++;
      if (!_backend) return;
      // Web autoplay unlock: the first play() comes from a tap, so this is
      // the earliest moment the browser lets music start. Retried (with a
      // small backoff) until it succeeds.
      if (_musicOn && !_musicPlaying && !_inBackground) {
        if (now - _lastMusicAttemptMs > 1500) unawaited(startMusic());
      }
      unawaited(_playSfx(sfx));
    } catch (e) {
      _log('play($sfx) failed: $e');
    }
  }

  static Future<void> _playSfx(Sfx sfx) async {
    try {
      final pool = await (_pools[sfx] ??= _SfxPool.create(sfx));
      await pool?.play();
    } catch (e) {
      _log('sfx $sfx failed: $e');
    }
  }

  /// Starts (or resumes) the music loop if music is on and not muted.
  /// Safe to call before init() finishes and before a user gesture on web:
  /// if the browser blocks it, the next play() retries.
  static Future<void> startMusic() {
    return _musicStarting ??= _startMusic().whenComplete(
      () => _musicStarting = null,
    );
  }

  static Future<void> _startMusic() async {
    try {
      _lastMusicAttemptMs = _clock.elapsedMilliseconds;
      await init();
      if (!_backend || !_musicOn || _muted || _inBackground) return;
      final player = await (_musicFuture ??= _createMusicPlayer());
      if (player == null || _musicPlaying) return;
      await player.resume().timeout(const Duration(seconds: 3));
      // Settings may have changed while we were waiting.
      if (!_musicOn || _muted || _inBackground) {
        await player.pause();
        return;
      }
      _musicPlaying = true;
    } catch (e) {
      _musicPlaying = false;
      _log('music start deferred: $e');
    }
  }

  /// Stops the music (position resets). Never throws.
  static Future<void> stopMusic() async {
    _musicPlaying = false;
    try {
      final player = await _musicFuture;
      await player?.stop();
    } catch (e) {
      _log('stopMusic failed: $e');
    }
  }

  static Future<void> _pauseMusic() async {
    _musicPlaying = false;
    try {
      final player = await _musicFuture;
      await player?.pause();
    } catch (e) {
      _log('pauseMusic failed: $e');
    }
  }

  /// Mutes or unmutes everything (SFX and music) and persists the choice.
  static void setMuted(bool value) {
    try {
      if (_muted == value) return;
      _muted = value;
      changes.value++;
      unawaited(_save(_kMuted, value));
      unawaited(value ? _pauseMusic() : startMusic());
    } catch (e) {
      _log('setMuted failed: $e');
    }
  }

  /// Turns the music on or off and persists the choice.
  static void setMusicOn(bool value) {
    try {
      if (_musicOn == value) return;
      _musicOn = value;
      changes.value++;
      unawaited(_save(_kMusicOn, value));
      unawaited(value ? startMusic() : _pauseMusic());
    } catch (e) {
      _log('setMusicOn failed: $e');
    }
  }

  static void _onLifecycle(AppLifecycleState state) {
    try {
      switch (state) {
        case AppLifecycleState.paused:
        case AppLifecycleState.hidden:
        case AppLifecycleState.detached:
          if (_inBackground) return;
          _inBackground = true;
          unawaited(_pauseMusic());
        case AppLifecycleState.resumed:
          if (!_inBackground) return;
          _inBackground = false;
          if (_musicOn && !_muted) unawaited(startMusic());
        case AppLifecycleState.inactive:
          break; // transient (control center, permission dialogs)
      }
    } catch (e) {
      _log('lifecycle failed: $e');
    }
  }

  static Future<void> _save(String key, bool value) async {
    try {
      final prefs = _prefs ??= await SharedPreferences.getInstance();
      await prefs.setBool(key, value);
    } catch (e) {
      _log('save $key failed: $e');
    }
  }

  static Future<void> _configureAudioContext() async {
    if (kIsWeb) return;
    try {
      // Ambient on iOS: respects the silent switch and mixes with the
      // player's own music. Android: game usage, no audio-focus grab.
      await AudioPlayer.global.setAudioContext(
        AudioContext(
          iOS: AudioContextIOS(category: AVAudioSessionCategory.ambient),
          android: const AudioContextAndroid(
            contentType: AndroidContentType.sonification,
            usageType: AndroidUsageType.game,
            audioFocus: AndroidAudioFocus.none,
          ),
        ),
      );
    } catch (e) {
      _log('audio context failed: $e');
    }
  }

  static Future<AudioPlayer?> _createMusicPlayer() async {
    if (!_backend) return null;
    try {
      final player = AudioPlayer(playerId: 'music');
      await player.setReleaseMode(ReleaseMode.loop);
      await player.setVolume(musicVolume);
      await player
          .setSource(AssetSource(musicAsset))
          .timeout(const Duration(seconds: 15));
      return player;
    } catch (e) {
      _log('music preload failed: $e');
      return null;
    }
  }

  static bool _isTestEnvironment() {
    try {
      // AutomatedTestWidgetsFlutterBinding / LiveTestWidgetsFlutterBinding.
      return WidgetsBinding.instance.runtimeType.toString().contains('Test');
    } catch (_) {
      return true; // no binding: plugins are unusable anyway
    }
  }

  static void _log(String message) {
    if (kDebugMode) debugPrint('[Sound] $message');
  }
}

/// A few preloaded players for one effect, used round-robin so rapid
/// repeats overlap instead of cutting each other off.
class _SfxPool {
  _SfxPool(this.players);

  final List<AudioPlayer> players;
  int _next = 0;

  static Future<_SfxPool?> create(Sfx sfx) async {
    final players = <AudioPlayer>[];
    try {
      // SoundPool on Android gives much lower latency for short effects.
      final mode = !kIsWeb && defaultTargetPlatform == TargetPlatform.android
          ? PlayerMode.lowLatency
          : PlayerMode.mediaPlayer;
      for (var i = 0; i < Sound._poolSize(sfx); i++) {
        final p = AudioPlayer(playerId: 'sfx_${sfx.name}_$i');
        await p.setPlayerMode(mode);
        await p.setReleaseMode(ReleaseMode.stop);
        await p.setVolume(Sound.sfxVolume(sfx));
        await p
            .setSource(AssetSource(Sound.assetFor(sfx)))
            .timeout(const Duration(seconds: 10));
        players.add(p);
      }
    } catch (e) {
      Sound._log('preload ${sfx.name} failed: $e');
    }
    return players.isEmpty ? null : _SfxPool(players);
  }

  Future<void> play() async {
    final p = players[_next];
    _next = (_next + 1) % players.length;
    await p.stop();
    await p.resume();
  }
}
